    def classify_triangle_by_sides(p1, p2, p3):
        from math import isclose
        a = abs(complex(*p1) - complex(*p2)) ** 2
        b = abs(complex(*p2) - complex(*p3)) ** 2
        c = abs(complex(*p3) - complex(*p1)) ** 2
        if isclose(a, b) and isclose(b, c):
            return 'equilateral'
        elif isclose(a, b) or isclose(b, c) or isclose(c, a):
            return 'isosceles'
        else:
            return 'scalene'

