                self.direction = (self.direction - 1) % 4
            elif command == 'R':
                self.direction = (self.direction + 1) % 4
            elif command == 'F':
                dx = [0, 1, 0, -1][self.direction]
                dy = [1, 0, -1, 0][self.direction]
