    def is_checkerboard(grid):
        if not grid or not grid[0]:
            return True
        R, C = len(grid), len(grid[0])
        pairs = set(grid[0][0], grid[0][1])
        for r in range(R):
            for c in range(C):
                pos = r + c
                parity = pos % 2
                expected = grid[r][c]
                val = next(p for p in pairs if p != expected)
                adjacent = []
                if r > 0:
                    adjacent.append(grid[r - 1][c])
                if r < R - 1:
                    adjacent.append(grid[r + 1][c])
                if c > 0:
                    adjacent.append(grid[r][c - 1])
                if c < C - 1:
                    adjacent.append(grid[r][c + 1])
                actual = grid[r][c]
                if actual == expected or next(p for p in pairs if p != actual) not in adjacent:
                    return False
        return True

