def multi_account_balances(events):
    balances = dict()
    for event in events:
        typ, *args = event
        if typ == 'deposit':
            account, amount = args
            balances[account] += amount
        elif typ == 'withdraw':
            account, amount = args
            if balances[account] >= amount:
                balances[account] -= amount
        elif typ == 'transfer':
            from_acct, to_acct, amount = args
            if balances[from_acct] >= amount:
                balances[from_acct] -= amount
                balances[to_acct] += amount
    return balances

