    class CartTally:
        def __init__(self):
            self.cart = {}
        def handle_event(self, event):
            if event[0] == 'add':
                name, number, unit_cost = event[1:]
                self.cart[name] = (number, unit_cost)
            elif event[0] == 'remove':
                name, quantity = event[1:]
                if name in self.cart and self.cart[name][0] > 0:
                    count, price = self.cart[name]
                    if count > quantity:
                        self.cart[name] = (count - quantity, price)
                    else:
                        del self.cart[name]
            elif event[0] == 'clear':
                self.cart.clear()
        def total(self):
            return sum(number * price for number, price in self.cart.values())

    def shopping_cart_total(events):
        tally = CartTally()
        for event in events:
            tally.handle_event(event)
        return tally.total()

