    facing = 0  # 0 = north, 1 = east, 2 = south, 3 = west
    cleaned = {(0, 0)}
    for c in commands:
        if c == 'L':
            facing = (facing - 1) % 4
        elif c == 'R':
            facing = (facing + 1) % 4
        else:  # 'F'
            di, dj = [(-1, 0), (0, 1), (1, 0), (0, -1)][facing]
