            red_intervals.append((red_start, red_end))
            red_start += red_duration + green_duration
            red_end += red_duration + green_duration
        crossings = []
        for arrival in arrivals:
            for start, end in red_intervals:
                if start >= arrival:
                    crossings.append(start)
