    def pedestrian_crossing_ticks(arrivals, red_duration, green_duration):
        for t in arrivals:
            cycle_start = t // (red_duration + green_duration) * (red_duration + green_duration)
            cycle_position = t - cycle_start
            if cycle_position < red_duration:
                yield cycle_start + cycle_position
            else:
