    def anti_diagonal(grid):
        rows = len(grid)
        cols = rows and len(grid[0]) or 0
        visited = set()
        while True:
            cell = None
            for j in range(cols):
                i = rows - 1 - j
                if 0 <= i < rows and (i, j) not in visited:
                    cell = i, j
                    break
            if not cell:
                break
